    // Calendar-only delivery dates must not shift into the previous local day.
    formatBusinessDate(value) {
        if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
            const [year, month, day] = value.split('-').map(Number);
