/* stylelint-enable color-no-hex */

body {
    font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg-light);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
}

/* Page Container */
.quote-page {
    min-height: 100vh;
    padding: 20px;
}

.quote-container {
    max-width: 900px;
    margin: 0 auto;
    background: var(--bg-white);
