    margin-bottom: 20px;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Error State */
.error-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 400px;
    text-align: center;
    padding: 40px;
}

.error-icon {
    width: 80px;
    height: 80px;
    background: var(--danger-light);
    color: var(--danger-color);
    border-radius: 50%;
