    align-items: center;
    justify-content: center;
    font-size: 40px;
    font-weight: bold;
    margin-bottom: 20px;
}

.error-state h2 {
    color: var(--danger-color);
    margin-bottom: 10px;
}

.error-state p {
    color: var(--text-secondary);
    margin-bottom: 10px;
}

.error-help a {
    color: var(--primary-color);
}

/* Header - Green gradient (compact) */
.quote-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px 25px;
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--primary-dark) 100%);
    color: white;
}

.header-left {
    flex-shrink: 0;
}

.company-logo {
    max-width: 160px;
    height: auto;
}

.logo-container {
    background: white;
    padding: 8px 12px;
    border-radius: 8px;
    display: inline-block;
}

.header-right {
