    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 8px;
}

.form-group input {
    width: 100%;
    padding: 12px 16px;
    font-size: 1rem;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    transition: border-color 0.2s;
}

.form-group input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgb(76 179 84 / 10%);
}

.form-info {
    background: var(--bg-light);
    padding: 16px;
    border-radius: var(--radius-sm);
    font-size: 0.9rem;
}

.form-info p {
    margin: 4px 0;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 20px 24px;
    border-top: 1px solid var(--border-color);
}

/* Success Modal */
.success-modal {
    text-align: center;
    padding: 40px;
}

.success-icon {
    width: 80px;
    height: 80px;
    background: var(--success-light);
    color: var(--success-color);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 40px;
    margin: 0 auto 24px;
}

.success-modal h2 {
    color: var(--success-color);
    margin-bottom: 16px;
}

.success-modal p {
    color: var(--text-secondary);
    margin-bottom: 16px;
}

.success-contact a {
    color: var(--primary-color);
}

.success-modal .btn {
    margin-top: 16px;
}

/* No items state */
.no-items {
    text-align: center;
    padding: 40px;
    color: var(--text-muted);
    font-style: italic;
}

/* Product Table - Quote Builder Style */
.product-table-wrapper {
    overflow-x: auto;
    background: white;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
}

.product-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 900px;
}

.product-table thead {
    background: var(--quote-view-cyan-dark);
    color: white;
}

.product-table th {
    padding: 12px 8px;
    text-align: center;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-right: 1px solid rgb(255 255 255 / 10%);
    white-space: nowrap;
}

.product-table th:last-child {
    border-right: none;
}

.product-table th.style-col {
    text-align: left;
    padding-left: 15px;
    min-width: 100px;
}

.product-table th.desc-col {
    text-align: left;
    min-width: 180px;
}

.product-table th.color-col {
    min-width: 100px;
}

.product-table th.size-col {
    min-width: 45px;
    letter-spacing: 0;
}

.product-table th.qty-col {
    min-width: 50px;
    letter-spacing: 0;
}

.product-table th.price-col,
.product-table th.total-col {
    min-width: 80px;
}

.product-table td {
    padding: 10px 8px;
    text-align: center;
    border-bottom: 1px solid var(--border-color);
    font-size: 0.9rem;
    vertical-align: middle;
}

.product-table td.style-col {
    text-align: left;
    padding-left: 10px;
    font-weight: 600;
    color: var(--primary-color);
    max-width: 280px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.product-table td.desc-col {
    text-align: left;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.product-table td.color-col {
    font-size: 0.85rem;
}

.product-table td.size-col {
    font-weight: 600;
    color: var(--text-primary);
    text-align: center;
    min-width: 45px;
}

.product-table td.size-col:not(:empty) {
    background: rgb(76 179 84 / 8%);
}

.product-table td.qty-col {
    font-weight: 600;
    color: var(--primary-color);
    text-align: center;
    min-width: 50px;
}

.product-table td.price-col,
.product-table td.total-col {
    text-align: right;
    padding-right: 12px;
    font-weight: 600;
}

.product-table td.total-col {
    color: var(--primary-color);
}

/* Style column with image */
.style-with-image {
    display: flex;
    align-items: center;
    gap: 8px;
}

.style-with-image span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.product-thumb {
    width: 40px;
    height: 40px;
    object-fit: contain;
    border-radius: 4px;
    border: 1px solid var(--border-color);
    background: white;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.product-thumb[src*="http"] {
    opacity: 1;
}

/* Row styles */
.product-table tr.first-row {
    background: white;
}

.product-table tr.first-row:hover {
    background: var(--gray-50);
}

.product-table tr.extended-row {
    background: var(--store-paper);
}

.product-table tr.extended-row:hover {
    background: var(--store-rush-soft);
}

.product-table tr.extended-row td.style-col {
    color: var(--amber-700);
    font-size: 0.85rem;
}

.product-table tr.extended-row td.desc-col {
    color: var(--amber-800);
}

/* Method subheads — mixed-method (WQ web-cart) quotes only (2026-06-11) */
.product-table tr.method-subhead td {
    padding: 8px 10px 6px;
    background-color: var(--slate-50);
    border-top: 2px solid var(--gray-300);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--gray-700);
}

/* Fee line items (Additional Stitches, AL charges, Digitizing) */
.product-table tr.fee-row {
    background-color: var(--brand-50);
    border-top: 1px dashed var(--green-300);
}

.product-table tr.fee-row:first-of-type {
    border-top: 2px solid var(--brand-500);
}

.product-table tr.fee-row td {
    font-style: italic;
}

.product-table tr.fee-row td.fee-part {
    font-family: 'Courier New', Courier, monospace;
    font-weight: 600;
    color: var(--green-700);
    font-style: normal;
}

.product-table tr.fee-row td.fee-desc {
    color: var(--print-green);
}

.product-table tr.fee-row td.total-col {
    color: var(--green-700);
    font-weight: 600;
}

/* Customer-supplied items (DECG/DECC) */
.product-table tr.customer-supplied-row {
    border-top: 1px solid var(--gray-200);
}

.product-table tr.customer-supplied-row td {
    font-style: normal;
}

.product-table tr.customer-supplied-row td.style-col {
    font-weight: 600;
}

.product-table tr.customer-supplied-row td.total-col {
    font-weight: 600;
}

/* Discount row (negative fee) - red styling */
.product-table tr.discount-row {
    background-color: var(--red-50);
    border-top: 1px dashed var(--red-300);
}

.product-table tr.discount-row td.fee-part {
    color: var(--red-600);
}

.product-table tr.discount-row td.fee-desc {
    color: var(--red-700);
}

.product-table tr.discount-row td.total-col,
.product-table tr.discount-row td.price-col {
    color: var(--red-600);
    font-weight: 600;
}

/* Color badge in table */
.color-badge-inline {
    display: inline-block;
    padding: 3px 10px;
    background: var(--primary-color);
    color: white;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 500;
}

/* Compact table styles */
.product-table.compact {
    min-width: 700px;
}

.product-table.compact th,
.product-table.compact td {
    padding: 8px 6px;
}

.product-table.compact .size-col {
    min-width: 38px;
}

.product-table td.clickable {
    cursor: pointer;
}

.product-table td.clickable:hover {
    background: rgb(76 179 84 / 15%);
}

.product-table td.ext-style {
    font-size: 0.8rem;
    color: var(--amber-700);
}

/* Embroidery Info Section */
.embroidery-info {
    display: flex;
    gap: 20px;
    padding: 12px 15px;
    background: var(--brand-100);
    border: 1px solid var(--primary-color);
    border-radius: var(--radius-sm);
    margin-bottom: 15px;
    flex-wrap: wrap;
}

.emb-detail {
    font-size: 0.9rem;
}

.emb-label {
    font-weight: 600;
    color: var(--primary-dark);
}

.emb-value {
    color: var(--text-primary);
}

/* Product Detail Modal */
.product-modal {
    position: fixed;
    inset: 0;
    z-index: 2000;
    display: flex;
    align-items: center;
    justify-content: center;
}

.product-modal.hidden {
    display: none;
}

.product-modal-backdrop {
    position: absolute;
    inset: 0;
    background: rgb(0 0 0 / 60%);
}

.product-modal-content {
    position: relative;
    background: white;
    border-radius: var(--radius-lg);
    max-width: 450px;
    width: 90%;
    box-shadow: var(--shadow-lg);
    animation: modalSlideIn 0.25s ease;
    overflow: hidden;
}

.product-modal-close {
    position: absolute;
    top: 10px;
    right: 15px;
    background: none;
    border: none;
    font-size: 28px;
    cursor: pointer;
    color: var(--text-muted);
    z-index: 10;
    line-height: 1;
}

.product-modal-close:hover {
    color: var(--text-primary);
}

.product-modal-body {
    text-align: center;
    padding: 20px;
}

.product-modal-image {
    max-width: 100%;
    max-height: 300px;
    object-fit: contain;
    border-radius: var(--radius-md);
    margin-bottom: 15px;
}

.product-modal-details h3 {
    font-size: 1.25rem;
    color: var(--text-primary);
    margin-bottom: 10px;
}

.product-modal-details .modal-style,
.product-modal-details .modal-color {
    font-size: 0.95rem;
    color: var(--text-secondary);
    margin: 5px 0;
}

.product-modal-details .modal-style span,
.product-modal-details .modal-color span {
    font-weight: 600;
    color: var(--primary-color);
}

/* Responsive */
@media (width <= 768px) {
    .quote-page {
        padding: 10px;
    }

    .quote-header {
        flex-direction: column;
        text-align: center;
        padding: 20px;
        gap: 16px;
    }

    .header-right {
        text-align: center;
    }

    .company-logo {
        max-width: 140px;
    }

    .quote-meta {
        grid-template-columns: 1fr;
        padding: 20px;
    }

    .quote-items,
    .quote-totals,
    .quote-actions {
        padding: 20px;
    }

    .product-header {
        flex-direction: column;
        text-align: center;
    }

    .product-total {
        margin-top: 10px;
        text-align: center;
    }

    .size-matrix th,
    .size-matrix td {
        padding: 6px 4px;
        font-size: 0.75rem;
    }

    .size-matrix th.size-col {
        min-width: 30px;
    }

    /* Product table responsive */
    .product-table-wrapper {
        margin: 0 -10px;
        border-radius: 0;
        border-left: none;
        border-right: none;
    }

    .product-table {
        min-width: 700px;
    }

    .product-table th,
    .product-table td {
        padding: 8px 4px;
        font-size: 0.75rem;
    }

    .product-table th.desc-col,
    .product-table td.desc-col {
        min-width: 120px;
    }

    .product-thumb {
        width: 30px;
        height: 30px;
    }

    .totals-card {
        max-width: 100%;
    }

    .quote-actions {
        flex-direction: column;
    }

    .btn {
        width: 100%;
        justify-content: center;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 24px;
    }

    .quote-footer {
        padding: 20px;
    }

    .dtf-specs {
        margin: 0 20px 20px;
    }

}

/* Print Styles */

/* Phase 11 (2026-05-14): @media print rules moved to shared_components/css/quote-print.css for cleaner separation. Loaded via <link media="print"> in quote-view.html. */

/* ============================================================
   DESIGN THUMBNAILS (2026-02-23)
   ============================================================ */
.quote-view-design-thumb {
    width: 60px;
    height: 60px;
    border-radius: 6px;
    object-fit: cover;
    border: 1px solid var(--gray-200);
    cursor: pointer;
    transition: box-shadow 0.2s, transform 0.2s;
    background: var(--color-surface);
}

.quote-view-design-thumb:hover {
    box-shadow: 0 2px 8px rgb(0 0 0 / 15%);
    transform: scale(1.05);
}

/* Full-size thumbnail overlay */
.thumb-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgb(0 0 0 / 70%);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10000;
    cursor: pointer;
}

.thumb-modal-overlay img {
    max-width: 90vw;
    max-height: 90vh;
    border-radius: 8px;
    box-shadow: 0 4px 24px rgb(0 0 0 / 30%);
    background: var(--color-surface);
}

/* ============================================================================
   ShopWorks Sync Strip (Erik 2026-05-21)
   ============================================================================
   Status pill + Refresh button banner that lives between the quote header
   and the customer-meta panels. Three visual states:
     - Pending  → gray pill with hourglass
     - Imported → forest-green pill with checkmark + WO#
     - Failed   → amber pill with warning sign (transient — only on refresh)
   ============================================================================ */

/* CANCELLED-IN-SHOPWORKS banner — full-width red strip above the sync
   strip when the ShopWorks operator deleted the order. The quote row
   stays in Caspio for 30 days for audit; bulk-sync cron purges later. */
.sw-cancelled-banner {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: var(--red-50);
    border: 2px solid var(--red-700);
    border-radius: 6px;
    margin: 12px 0 18px;
    color: var(--print-red);
    font-size: 14px;
    line-height: 1.4;
}

.sw-cancelled-icon {
    font-size: 22px;
    line-height: 1;
    color: var(--red-700);
}

.sw-cancelled-text strong {
    display: inline-block;
    font-weight: 800;
    color: var(--red-700);
    letter-spacing: 0.04em;
    margin-right: 6px;
}

.sw-cancelled-detail {
    color: var(--print-red);
    font-weight: 500;
}

.sw-sync-strip {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
    justify-content: space-between;
    margin: 12px 0 18px;
    padding: 10px 14px;
    background: linear-gradient(180deg, var(--slate-50) 0%, var(--slate-100) 100%);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
    font-size: 13px;
}

.sw-sync-left {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.sw-sync-right {
    display: flex;
    align-items: center;
    gap: 12px;
}

.sw-sync-pill {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 12px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.01em;
    line-height: 1.4;
    transition: background-color 180ms ease, color 180ms ease;
}

.sw-sync-pill-icon {
    font-size: 12px;
    line-height: 1;
}

.sw-sync-pill--pending {
    background: var(--slate-100);
    color: var(--slate-600);
    border: 1px solid var(--gray-300);
}

.sw-sync-pill--imported {
    background: var(--store-green-100);
    color: var(--print-green-dark);
    border: 1px solid var(--green-300);
}

.sw-sync-pill--unknown {
    background: var(--amber-100);
    color: var(--amber-900);
    border: 1px solid var(--amber-300);
}

.sw-sync-extorder {
    font-size: 11px;
    font-weight: 500;
    color: var(--slate-500);
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    letter-spacing: 0.02em;
}

.sw-sync-timestamp {
    font-size: 11px;
    color: var(--slate-500);
}

.sw-sync-refresh-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: var(--color-surface);
    border: 1px solid var(--gray-300);
    border-radius: 6px;
    font: inherit;
    font-size: 12px;
    font-weight: 600;
    color: var(--gray-700);
    cursor: pointer;
    transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.sw-sync-refresh-btn:hover:not(:disabled) {
    background: var(--slate-100);
    border-color: var(--gray-400);
    color: var(--gray-900);
}

.sw-sync-refresh-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.sw-sync-refresh-btn--loading .sw-sync-refresh-icon {
    animation: sw-sync-spin 0.9s linear infinite;
}

@keyframes sw-sync-spin {
    from { transform: rotate(0deg); }
    to   { transform: rotate(360deg); }
}

.sw-sync-refresh-icon {
    font-size: 13px;
    line-height: 1;
    display: inline-block;
}

@media (width <= 600px) {
    .sw-sync-strip {
        flex-direction: column;
        align-items: flex-start;
    }

    .sw-sync-right {
        width: 100%;
        justify-content: space-between;
    }
}

@media print {
    .sw-sync-strip { display: none !important; }
}

/* ============================================================================
   Phase 4b — ShopWorks Designs panel + mirrored-fields indicator
   ============================================================================ */

/* Subtle indicator on meta cards showing they reflect live ShopWorks data */
.meta-card.sw-mirrored {
    position: relative;
}

.meta-card.sw-mirrored::after {
    content: "ShopWorks ✓";
    position: absolute;
    top: 8px;
    right: 10px;
    padding: 2px 8px;
    background: var(--store-green-100);
    color: var(--print-green-dark);
    border: 1px solid var(--green-300);
    border-radius: 999px;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    pointer-events: none;
}

/* Designs panel — mirrors the ShopWorks PDF "Designs" block */
.sw-designs-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-designs-section h2 {
    margin: 0 0 16px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}

.sw-designs-meta {
    display: flex;
    gap: 24px;
    margin-bottom: 16px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--slate-100);
}

.sw-designs-counter {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sw-designs-counter-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
}

.sw-designs-counter-value {
    font-size: 24px;
    font-weight: 700;
    color: var(--gray-900);
    line-height: 1.1;
}

.sw-designs-table-wrap {
    overflow-x: auto;
}

.sw-designs-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

.sw-designs-table thead th {
    text-align: left;
    padding: 8px 12px;
    background: var(--slate-50);
    border-bottom: 2px solid var(--slate-200);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--slate-600);
}

.sw-designs-table tbody td {
    padding: 12px;
    border-bottom: 1px solid var(--slate-100);
    color: var(--gray-700);
}

.sw-designs-table tbody tr:last-child td {
    border-bottom: none;
}

.sw-designs-id {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-weight: 600;
    color: var(--gray-900);
    width: 80px;
}

/* Design-library thumbnail column (filled async by _loadDesignPanelThumbnails) */
.sw-designs-th-thumb,
.sw-designs-thumb-cell {
    width: 56px;
}

.sw-designs-thumb-cell .sw-designs-thumb {
    display: none;   /* stays hidden until a thumbnail mounts */
}

.sw-designs-name {
    font-weight: 600;
    color: var(--gray-900);
}

.sw-designs-type {
    color: var(--slate-600);
    width: 100px;
}

.sw-designs-locations,
.sw-designs-imprints {
    text-align: center;
    width: 90px;
    color: var(--slate-600);
}

@media print {
    .meta-card.sw-mirrored::after { display: none; }  /* don't print the ShopWorks badge */
}

/* ============================================================================
   Phase 4c — Order Status grid + Notes panel + Shipping panel
   ============================================================================ */

/* Order Status grid — 10-tile responsive grid */
.sw-status-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-status-section h2 {
    margin: 0 0 16px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}

.sw-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
    gap: 12px;
}

.sw-status-cell {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 12px 8px;
    background: var(--slate-50);
    border: 1px solid var(--slate-200);
    border-radius: 8px;
    transition: transform 120ms ease, box-shadow 120ms ease;
}

.sw-status-cell:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 6px rgb(0 0 0 / 6%);
}

.sw-status-cell-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
    text-align: center;
}

.sw-status-cell-value {
    display: inline-block;
    min-width: 50px;
    padding: 4px 12px;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 700;
    text-align: center;
    line-height: 1.3;
    border: 1.5px solid transparent;
}

.sw-status-cell-value--yes {
    background: var(--store-green-100);
    color: var(--print-green-dark);
    border-color: var(--green-300);
}

.sw-status-cell-value--no {
    background: var(--red-100);
    color: var(--print-red);
    border-color: var(--red-300);
}

/* ShopWorks 3rd/4th states (Erik 2026-06-16): Partial (.5), N/A (8/222), and
   unknown/not-yet-synced ("—") — mirror the OnSite order screen, neutral tones. */
.sw-status-cell-value--partial {
    background: var(--amber-100);
    color: var(--amber-800);
    border-color: var(--amber-300);
}

.sw-status-cell-value--na,
.sw-status-cell-value--unknown {
    background: var(--slate-100);
    color: var(--slate-500);
    border-color: var(--gray-300);
}

/* Notes To Production — numbered list mirroring the ShopWorks PDF */
.sw-notes-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-notes-section h2 {
    margin: 0 0 12px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}

.sw-notes-list {
    margin: 0;
    padding-left: 28px;
    list-style-type: decimal;
    list-style-position: outside;
    font-size: 13px;
    line-height: 1.55;
    color: var(--gray-700);
}

.sw-notes-list li {
    padding: 4px 0;
    border-bottom: 1px dashed var(--slate-100);
}

.sw-notes-list li:last-child {
    border-bottom: none;
}

.sw-notes-list li::marker {
    color: var(--gray-400);
    font-weight: 600;
}

.sw-notes-footer {
    margin-top: 12px;
    padding: 10px 12px;
    background: var(--store-rush-soft);
    border: 1px solid var(--quote-view-yellow);
    border-radius: 6px;
    font-size: 11.5px;
    color: var(--amber-900);
    line-height: 1.4;
}

/* Shipping panel */
.sw-shipping-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-shipping-section h2 {
    margin: 0 0 16px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}

/* Blank Goods — inbound vendor (SanMar) shipment (2026-06-15). Mirrors the
   shipping panel; reuses .sw-tracking-* for the per-box list. */
.sw-vendor-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-vendor-section h2 {
    margin: 0 0 16px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}
.sw-vendor-po-block { margin-bottom: 14px; }
.sw-vendor-po-block:last-child { margin-bottom: 0; }
.sw-vendor-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 10px; }
.sw-vendor-po { font-weight: 700; color: var(--gray-700); font-size: 14px; }
.sw-vendor-pill { font-size: 12px; font-weight: 700; padding: 3px 10px; border-radius: 999px; border: 1px solid transparent; }

.sw-vendor-pill--confirmed,
.sw-vendor-pill--unknown { background: var(--slate-100); color: var(--slate-600); border-color: var(--gray-300); }
.sw-vendor-pill--partial { background: var(--amber-100); color: var(--amber-800); border-color: var(--amber-300); }

.sw-vendor-pill--shipped,
.sw-vendor-pill--complete { background: var(--store-green-100); color: var(--print-green); border-color: var(--green-300); }
.sw-vendor-pill--canceled { background: var(--red-100); color: var(--red-800); border-color: var(--red-300); }
.sw-vendor-eta { font-size: 12px; color: var(--slate-500); }
.sw-vendor-note { font-size: 13px; color: var(--slate-600); padding: 4px 0; }
.sw-vendor-note--warn { color: var(--amber-800); }
.sw-vendor-loading { font-size: 13px; color: var(--gray-400); }
.sw-vendor-empty { font-size: 13px; color: var(--slate-500); }
.sw-vendor-error { font-size: 13px; color: var(--red-700); }

.sw-shipping-meta {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    margin-bottom: 16px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--slate-100);
}

.sw-shipping-meta-row {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 110px;
}

.sw-shipping-meta-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
}

.sw-shipping-meta-value {
    font-size: 14px;
    font-weight: 600;
    color: var(--gray-900);
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.sw-shipping-address-block {
    font-size: 14px;
    line-height: 1.5;
    color: var(--gray-700);
}

.sw-shipping-recipient {
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 2px;
}

.sw-shipping-method {
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--slate-100);
    font-weight: 600;
    color: var(--quote-green, var(--brand-500));
}

.sw-shipping-mode {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid var(--slate-100);
}

.sw-shipping-mode-pill {
    padding: 4px 12px;
    background: var(--slate-50);
    border: 1px solid var(--gray-300);
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
    color: var(--slate-500);
    transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.sw-shipping-mode-pill::before {
    content: "○";
    margin-right: 4px;
    font-size: 14px;
    line-height: 1;
}

.sw-shipping-mode-pill--active {
    background: var(--quote-green-light, var(--material-green-100));
    border-color: var(--quote-green, var(--brand-500));
    color: var(--quote-green-dark, var(--store-green-700));
}

.sw-shipping-mode-pill--active::before {
    content: "●";
}

/* ============================================================================
   Manual ShopWorks WO# entry strip (Erik 2026-05-21)
   ============================================================================
   Workaround for the MO /v1/getorderno gap. Reps type the WO# they see in
   ShopWorks UI; we store it and use it for all future syncs on this quote.
*/
.sw-manual-wo-strip {
    margin: 8px 0 18px;
    padding: 12px 14px;
    background: linear-gradient(180deg, var(--store-rush-soft) 0%, var(--amber-100) 100%);
    border: 1px solid var(--quote-view-yellow);
    border-left: 4px solid var(--amber-600);
    border-radius: 8px;
}

.sw-manual-wo-left {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: center;
}

.sw-manual-wo-icon {
    font-size: 16px;
    line-height: 1;
}

.sw-manual-wo-label {
    font-size: 13px;
    font-weight: 600;
    color: var(--amber-900);
}

.sw-manual-wo-input {
    padding: 6px 10px;
    border: 1.5px solid var(--amber-600);
    border-radius: 6px;
    font: inherit;
    font-size: 14px;
    font-weight: 600;
    color: var(--gray-900);
    width: 110px;
    text-align: center;
    background: var(--color-surface);
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.sw-manual-wo-input:focus {
    outline: 2px solid var(--amber-700);
    outline-offset: 1px;
}

.sw-manual-wo-btn {
    padding: 6px 14px;
    background: var(--amber-600);
    border: 1.5px solid var(--amber-700);
    border-radius: 6px;
    color: var(--color-on-brand);
    font: inherit;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    transition: background-color 120ms ease;
}

.sw-manual-wo-btn:hover:not(:disabled) {
    background: var(--amber-700);
}

.sw-manual-wo-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.sw-manual-wo-help {
    margin-top: 8px;
    font-size: 11.5px;
    color: var(--amber-800);
    line-height: 1.4;
}

@media print {
    .sw-manual-wo-strip { display: none !important; }
}

/* ============================================================================
   Phase 4d — Artwork thumbnails grid (under Designs panel)
   ============================================================================ */
.sw-designs-locations-names {
    color: var(--slate-500);
    font-weight: 400;
    margin-left: 4px;
}

.sw-designs-artwork {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--slate-100);
}

.sw-designs-artwork-head {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
    margin-bottom: 12px;
}

.sw-designs-artwork-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
}

.sw-designs-artwork-card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
    background: var(--slate-50);
    border: 1px solid var(--slate-200);
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease;
}

.sw-designs-artwork-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgb(0 0 0 / 8%);
    border-color: var(--quote-green, var(--brand-500));
}

.sw-designs-artwork-thumb {
    width: 100%;
    aspect-ratio: 1 / 1;
    border-radius: 6px;
    overflow: hidden;
    background: var(--color-surface);
    border: 1px solid var(--slate-100);
    display: flex;
    align-items: center;
    justify-content: center;
}

.sw-designs-artwork-thumb img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.sw-designs-artwork-thumb-icon {
    font-size: 36px;
    color: var(--gray-400);
}

.sw-designs-artwork-meta {
    text-align: center;
}

.sw-designs-artwork-location {
    font-size: 12px;
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 2px;
}

.sw-designs-artwork-filename {
    font-size: 10.5px;
    color: var(--slate-500);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

@media print {
    .sw-designs-artwork-card { break-inside: avoid; }
}

/* ============================================================================
   Customer Artwork & Mockups (2026-06-10) — Custom T-Shirts storefront orders.
   Original uploaded art + approved mockup renders from OrderSettingsJSON.
   Mounted by quote-view.js renderCustomerArtwork(); styled to match the
   sw-designs-artwork strip above.
   ============================================================================ */
.cust-art-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 12px;
}

.cust-art-section h2 {
    font-size: 18px;
    font-weight: 700;
    color: var(--gray-900);
    margin: 0 0 4px;
}

.cust-art-subhead {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
    margin: 16px 0 12px;
}

.cust-art-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
}

.cust-art-card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
    background: var(--slate-50);
    border: 1px solid var(--slate-200);
    border-radius: 8px;
}

.cust-art-thumb {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    aspect-ratio: 1 / 1;
    border-radius: 6px;
    overflow: hidden;
    background: var(--color-surface);
    border: 1px solid var(--slate-100);
    text-decoration: none;
    color: inherit;
    transition: transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease;
}

.cust-art-thumb:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgb(0 0 0 / 8%);
    border-color: var(--quote-green, var(--brand-500));
}

.cust-art-thumb img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.cust-art-thumb-icon {
    font-size: 36px;
    color: var(--gray-400);
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    display: flex;
}

.cust-art-meta {
    text-align: center;
}

.cust-art-label {
    font-size: 12px;
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 2px;
}

.cust-art-filename {
    font-size: 10.5px;
    color: var(--slate-500);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.cust-art-download {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 6px;
    padding: 4px 12px;
    font-size: 12px;
    font-weight: 600;
    color: var(--color-on-brand);
    background: var(--quote-green, var(--brand-500));
    border-radius: 6px;
    text-decoration: none;
}

.cust-art-download:hover {
    filter: brightness(0.95);
}

@media print {
    .cust-art-card { break-inside: avoid; }
    .cust-art-download { display: none; } /* links are useless on paper */
}

/* ============================================================================
   Phase 4d — Financial Summary panel
   ============================================================================ */
.sw-financial-section {
    margin: 24px 0;
    padding: 20px;
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
}

.sw-financial-section h2 {
    margin: 0 0 16px;
    font-size: 18px;
    font-weight: 700;
    color: var(--quote-green, var(--brand-500));
    border-bottom: 2px solid var(--quote-green, var(--brand-500));
    padding-bottom: 8px;
}

.sw-financial-grid {
    display: flex;
    flex-direction: column;
    gap: 6px;
    max-width: 480px;
    margin-left: auto;
}

.sw-financial-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 12px;
    background: var(--slate-50);
    border-radius: 6px;
    font-size: 14px;
}

.sw-financial-label {
    font-weight: 500;
    color: var(--slate-600);
}

.sw-financial-value {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-weight: 600;
    color: var(--gray-900);
}

.sw-financial-row--total {
    background: var(--brand-50);
    border: 1px solid var(--green-300);
    margin-top: 6px;
}

.sw-financial-row--total .sw-financial-label {
    color: var(--print-green-dark);
    font-weight: 700;
}

.sw-financial-row--total .sw-financial-value {
    color: var(--quote-green-dark, var(--store-green-700));
    font-size: 16px;
}

.sw-financial-row--balance {
    background: var(--red-50);
    border: 1px solid var(--red-300);
}

.sw-financial-row--balance .sw-financial-label {
    color: var(--print-red);
    font-weight: 700;
}

.sw-financial-row--balance .sw-financial-value {
    color: var(--red-700);
    font-size: 16px;
    font-weight: 700;
}

.sw-financial-row--terms {
    background: transparent;
    border-top: 1px dashed var(--slate-200);
    margin-top: 4px;
    padding-top: 12px;
}

.sw-financial-row--terms .sw-financial-value {
    font-family: inherit;
    font-weight: 600;
    color: var(--slate-600);
}

@media (width <= 600px) {
    .sw-financial-grid {
        max-width: 100%;
    }
}

/* Tax-rate sublabel under the Sales Tax row */
.sw-financial-sublabel {
    display: inline-block;
    margin-left: 8px;
    padding: 1px 8px;
    background: var(--sky-100);
    color: var(--quote-view-cyan);
    border: 1px solid var(--quote-view-cyan-2);
    border-radius: 999px;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.02em;
    vertical-align: middle;
}

.sw-financial-sublabel:empty {
    display: none;
}

/* ============================================================================
   Phase 4e — View Original Submission audit panel
   ============================================================================ */
.sw-original-section {
    margin: 24px 0;
}

.sw-original-details {
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
    overflow: hidden;
}

.sw-original-summary {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 16px 20px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
    color: var(--gray-700);
    user-select: none;
    transition: background-color 120ms ease;
}

.sw-original-summary:hover {
    background: var(--slate-50);
}

.sw-original-details[open] .sw-original-summary {
    background: var(--slate-100);
    border-bottom: 1px solid var(--slate-200);
}

.sw-original-summary::-webkit-details-marker {
    display: none;
}

.sw-original-summary-icon {
    font-size: 14px;
    color: var(--gray-400);
    transition: transform 200ms ease;
    display: inline-block;
}

.sw-original-details[open] .sw-original-summary-icon {
    transform: rotate(90deg);
}

.sw-original-summary-title {
    color: var(--gray-900);
    font-weight: 700;
}

.sw-original-summary-meta {
    margin-left: auto;
    font-size: 12px;
    font-weight: 500;
    color: var(--slate-500);
}

.sw-original-summary-meta--changed {
    color: var(--amber-700);
    background: var(--store-rush-soft);
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    border: 1px solid var(--quote-view-yellow);
}

.sw-original-body {
    padding: 18px 20px 20px;
}

.sw-original-intro {
    font-size: 13px;
    color: var(--slate-500);
    line-height: 1.55;
    margin-bottom: 16px;
}

.sw-original-intro strong {
    color: var(--gray-900);
}

.sw-original-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
    font-size: 13px;
}

.sw-original-table thead th {
    text-align: left;
    padding: 8px 12px;
    background: var(--slate-50);
    border-bottom: 2px solid var(--slate-200);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--slate-600);
}

.sw-original-table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid var(--slate-100);
    vertical-align: top;
}

.sw-original-row--diff {
    background: linear-gradient(90deg, var(--store-rush-soft) 0%, var(--red-50) 100%);
}

.sw-original-row--diff td {
    border-bottom-color: var(--amber-400);
}

.sw-original-label {
    font-weight: 600;
    color: var(--gray-700);
    width: 30%;
}

.sw-original-value {
    color: var(--slate-600);
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 12.5px;
}

.sw-original-value--original {
    color: var(--gray-400);
    text-decoration: line-through;
}

.sw-original-row:not(.sw-original-row--diff) .sw-original-value--original {
    color: var(--gray-700);
    text-decoration: none;
}

.sw-original-value--current {
    color: var(--gray-900);
    font-weight: 600;
}

.sw-original-row:not(.sw-original-row--diff) .sw-original-value--current {
    font-weight: 400;
}

.sw-original-arrow {
    color: var(--amber-700);
    font-weight: 700;
    margin-right: 4px;
}

.sw-original-design-snapshot {
    padding: 10px 12px;
    background: var(--color-floor-tint);
    border: 1px solid var(--quote-view-cyan-tint);
    border-radius: 6px;
    margin-bottom: 16px;
    font-size: 12.5px;
    color: var(--quote-view-cyan);
}

.sw-original-subsection {
    margin-top: 16px;
}

.sw-original-subheader {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
    margin: 0 0 10px;
}

.sw-original-rows-list {
    list-style: none;
    margin: 0;
    padding: 0;
    border: 1px solid var(--slate-200);
    border-radius: 6px;
    overflow: hidden;
}

.sw-original-rows-list li {
    padding: 8px 12px;
    border-bottom: 1px solid var(--slate-100);
    font-size: 12.5px;
    color: var(--gray-700);
}

.sw-original-rows-list li:last-child {
    border-bottom: none;
}

.sw-original-rows-list li:nth-child(even) {
    background: var(--gray-50);
}

@media print {
    .sw-original-section { display: none !important; }
}

/* ============================================================================
   Quick Actions row (Erik 2026-05-21)
   ============================================================================ */
.sw-actions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 8px 0 16px;
    padding-bottom: 12px;
    border-bottom: 1px dashed var(--slate-200);
}

.sw-action-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: var(--color-surface);
    border: 1px solid var(--gray-300);
    border-radius: 6px;
    font: inherit;
    font-size: 12px;
    font-weight: 600;
    color: var(--gray-700);
    cursor: pointer;
    transition: all 120ms ease;
}

.sw-action-btn:hover {
    background: var(--slate-100);
    border-color: var(--gray-400);
    color: var(--gray-900);
    transform: translateY(-1px);
}

.sw-action-btn--success {
    background: var(--store-green-100);
    border-color: var(--green-300);
    color: var(--print-green-dark);
}

.sw-action-icon {
    font-size: 14px;
    line-height: 1;
}

/* ============================================================================
   Send to Steve modal (Erik 2026-06-26) — hosts the shared garment art form
   ============================================================================ */
.sts-modal {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding: 24px 16px;
    overflow-y: auto;
}

.sts-modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgb(15 23 42 / 55%);
}

.sts-modal-dialog {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 880px;
    margin: auto;
    background: var(--color-surface);
    border-radius: 12px;
    box-shadow: 0 24px 60px rgb(15 23 42 / 35%);
    padding: 20px 20px 28px;
}

.sts-modal-close {
    position: absolute;
    top: 10px;
    right: 12px;
    width: 34px;
    height: 34px;
    border: none;
    border-radius: 50%;
    background: var(--slate-100);
    color: var(--slate-600);
    font-size: 22px;
    line-height: 1;
    cursor: pointer;
    z-index: 2;
}
.sts-modal-close:hover { background: var(--slate-200); color: var(--gray-900); }

/* ============================================================================
   Payments list (below Financial Summary)
   ============================================================================ */
.sw-payments-list {
    margin-top: 18px;
    padding-top: 18px;
    border-top: 1px solid var(--slate-100);
}

.sw-payments-list-head {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--slate-500);
    margin: 0 0 10px;
}

.sw-payments-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

.sw-payments-table thead th {
    text-align: left;
    padding: 8px 12px;
    background: var(--slate-50);
    border-bottom: 1px solid var(--slate-200);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--slate-600);
}

.sw-payments-amount-col {
    text-align: right;
}

.sw-payments-table tbody td {
    padding: 8px 12px;
    border-bottom: 1px solid var(--slate-100);
    color: var(--gray-700);
}

.sw-payments-table tbody tr:last-child td {
    border-bottom: none;
}

.sw-payments-ref {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 12px;
    color: var(--slate-500);
}

.sw-payments-amount {
    text-align: right;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-weight: 700;
    color: var(--green-600);
}

/* ============================================================================
   Tracking block (inside Shipping panel)
   ============================================================================ */
.sw-tracking-block {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--slate-100);
}

.sw-tracking-head {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--quote-green, var(--brand-500));
    margin: 0 0 10px;
}

.sw-tracking-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.sw-tracking-list li {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    padding: 8px 12px;
    background: var(--color-floor-tint);
    border: 1px solid var(--quote-view-cyan-tint);
    border-radius: 6px;
    font-size: 13px;
}

.sw-tracking-carrier {
    font-weight: 700;
    color: var(--quote-view-cyan);
    min-width: 80px;
}

.sw-tracking-num {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 12.5px;
    flex: 1;
}

.sw-tracking-num a {
    color: var(--sky-700);
    text-decoration: underline;
}

.sw-tracking-date {
    font-size: 11.5px;
    color: var(--slate-500);
}

/* ============================================================================
   PRINT — print-mode rules for all the new ShopWorks-mirror sections
   ============================================================================ */
@media print {
    /* Hide interactive UI that's irrelevant on paper */
    .sw-sync-strip,
    .sw-manual-wo-strip,
    .sw-actions-row,
    .sw-original-section,
    .sw-sync-refresh-btn,
    .sts-modal {
        display: none !important;
    }

    /* Make panel headings consistent with the printed invoice tone */
    .sw-designs-section h2,
    .sw-status-section h2,
    .sw-notes-section h2,
    .sw-shipping-section h2,
    .sw-financial-section h2 {
        font-size: 13pt;
        color: var(--print-ink) !important;
        border-bottom: 1.5pt solid var(--brand-500) !important;
        padding-bottom: 4pt;
        break-after: avoid;
    }

    .sw-designs-section,
    .sw-status-section,
    .sw-notes-section,
    .sw-shipping-section,
    .sw-financial-section {
        margin: 12pt 0;
        padding: 8pt 10pt;
        background: var(--color-surface);
        border: 0.5pt solid var(--gray-300);
        break-inside: avoid;
    }

    .sw-status-cell {
        background: var(--color-surface);
        padding: 4pt 6pt;
    }

    .sw-status-cell-value--yes {
        background: var(--brand-100);
    }

    .sw-status-cell-value--no {
        background: var(--red-50);
    }

    /* Hide the "ShopWorks ✓" badge on cards when printing */
    .meta-card.sw-mirrored::after {
        display: none !important;
    }

    /* Tracking + payments rows should print cleanly */
    .sw-tracking-list li {
        background: var(--color-surface) !important;
        border: 0.5pt solid var(--gray-300) !important;
    }

    /* Artwork thumbnails — print at smaller size */
    .sw-designs-artwork-grid {
        grid-template-columns: repeat(4, 1fr);
        gap: 8pt;
    }

    .sw-designs-artwork-thumb {
        max-height: 80pt;
    }
}

/* ============================================================================
   Quote Timeline (#15, 2026-07-05) — collapsible event history.
   Mirrors the .sw-original-* details/summary pattern above.
   ============================================================================ */
.qv-timeline-section {
    margin: 16px 0 24px;
}

.qv-timeline-details {
    background: var(--color-surface);
    border: 1px solid var(--slate-200);
    border-radius: 10px;
    overflow: hidden;
}

.qv-timeline-summary {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 20px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
    color: var(--gray-700);
    user-select: none;
    transition: background-color 120ms ease;
}

.qv-timeline-summary:hover {
    background: var(--slate-50);
}

.qv-timeline-details[open] .qv-timeline-summary {
    background: var(--slate-100);
    border-bottom: 1px solid var(--slate-200);
}

.qv-timeline-summary::-webkit-details-marker {
    display: none;
}

.qv-timeline-summary-icon {
    font-size: 14px;
    color: var(--gray-400);
    transition: transform 200ms ease;
    display: inline-block;
}

.qv-timeline-details[open] .qv-timeline-summary-icon {
    transform: rotate(90deg);
}

.qv-timeline-summary-title {
    color: var(--gray-900);
    font-weight: 700;
}

.qv-timeline-summary-meta {
    margin-left: auto;
    font-size: 12px;
    font-weight: 500;
    color: var(--slate-500);
}

.qv-timeline-list {
    margin: 0;
    padding: 16px 20px 16px 34px;
    list-style: none;
    position: relative;
}

.qv-timeline-item {
    position: relative;
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 6px 8px;
    padding: 6px 0 6px 18px;
    font-size: 13px;
    color: var(--gray-700);
}

/* vertical connector line */
.qv-timeline-item::before {
    content: "";
    position: absolute;
    left: 4px;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--slate-200);
}
.qv-timeline-item:first-child::before { top: 50%; }
.qv-timeline-item:last-child::before { bottom: 50%; }
.qv-timeline-item:only-child::before { display: none; }

.qv-timeline-dot {
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--quote-green, var(--brand-500));
    border: 2px solid var(--color-surface);
    box-shadow: 0 0 0 1px var(--slate-200);
}

.qv-timeline-item--staff .qv-timeline-dot {
    background: var(--slate-500);
}

.qv-timeline-label {
    font-weight: 600;
    color: var(--gray-900);
}

.qv-timeline-detail {
    color: var(--slate-500);
}

.qv-timeline-staff-chip {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--slate-500);
    background: var(--slate-100);
    border: 1px solid var(--slate-200);
    border-radius: 999px;
    padding: 1px 8px;
}

/* Never print the timeline — staff-internal events must not land on
   customer-facing PDFs (matches .sw-original-section print behavior). */
@media print {
    .qv-timeline-section { display: none !important; }
}

/* ============================================================================
   Online deposit (Storefront Checkout Phase 1, 2026-07-05)
   Customer panel (#deposit-panel) + staff strip (#qv-deposit-strip).
   ============================================================================ */
.deposit-panel { margin: 8px 0 18px; }

.deposit-card {
    padding: 18px 20px;
    background: linear-gradient(180deg, var(--brand-50) 0%, var(--store-green-100) 100%);
    border: 1px solid var(--green-300);
    border-left: 4px solid var(--green-600);
    border-radius: 8px;
}

.deposit-title {
    margin: 0 0 12px;
    font-size: 18px;
    font-weight: 700;
    color: var(--print-green-dark);
}
.deposit-breakdown { margin-bottom: 10px; }

.deposit-line {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 4px 0;
    font-size: 14px;
    color: var(--gray-800);
}

.deposit-line-total {
    border-top: 1px solid var(--green-300);
    margin-top: 4px;
    padding-top: 8px;
    font-weight: 700;
}
.deposit-line-due { font-weight: 700; color: var(--print-green-dark); font-size: 16px; }
.deposit-line-paid { color: var(--print-green); }
.deposit-pay-btn { width: 100%; margin: 12px 0 8px; font-size: 16px; }
.deposit-note { margin: 6px 0 0; font-size: 12.5px; color: var(--slate-600); }

.deposit-banner {
    padding: 10px 14px;
    border-radius: 8px;
    font-size: 14px;
    margin-bottom: 10px;
}
.deposit-banner-ok { background: var(--store-green-100); border: 1px solid var(--green-300); color: var(--print-green-dark); }
.deposit-banner-warn { background: var(--amber-100); border: 1px solid var(--quote-view-yellow); color: var(--amber-900); }

/* Staff strip — mirrors the sw-manual-wo-strip visual language */
.qv-deposit-strip {
    margin: 8px 0 18px;
    padding: 12px 14px;
    background: linear-gradient(180deg, var(--color-floor-tint) 0%, var(--sky-100) 100%);
    border: 1px solid var(--quote-view-blue);
    border-left: 4px solid var(--quote-view-blue-2);
    border-radius: 8px;
}

.qv-deposit-strip-head {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 700;
    color: var(--quote-view-blue-4);
}

.qv-deposit-strip-state {
    margin-left: auto;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--slate-600);
    background: var(--color-surface);
    border: 1px solid var(--quote-view-blue-tint);
    border-radius: 999px;
    padding: 2px 10px;
}
.qv-deposit-strip-state.is-live { color: var(--indigo-700); border-color: var(--quote-view-blue); }
.qv-deposit-strip-state.is-paid { color: var(--print-green); background: var(--store-green-100); border-color: var(--green-300); }

.qv-deposit-strip-form {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 12px;
    margin-top: 10px;
}

.qv-deposit-field {
    display: flex;
    flex-direction: column;
    gap: 3px;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--quote-view-blue-5);
}

.qv-deposit-field input {
    width: 110px;
    padding: 6px 8px;
    border: 1px solid var(--quote-view-blue);
    border-radius: 6px;
    font-size: 14px;
}
.qv-deposit-preview { font-size: 13px; color: var(--slate-600); flex: 1 1 auto; }

.qv-deposit-enable-btn {
    padding: 8px 14px;
    background: var(--quote-view-blue-2);
    color: var(--color-on-brand);
    border: none;
    border-radius: 6px;
    font-weight: 700;
    font-size: 14px;
    cursor: pointer;
}
.qv-deposit-enable-btn:hover { background: var(--indigo-700); }
.qv-deposit-enable-btn:disabled { opacity: 0.6; cursor: default; }
.qv-deposit-strip-help { margin-top: 8px; font-size: 12px; color: var(--slate-500); }

/* Staff strip never prints; the customer deposit card DOES print (it is the
   payment terms of record on a saved PDF). */
@media print {
    .qv-deposit-strip { display: none !important; }
    .deposit-pay-btn { display: none !important; }
}

/* Delivery-method choice in the accept modal (pickup skip-the-rep, 2026-07-06) */
.qv-delivery-choice > label:first-child {
    display: block;
    font-weight: 600;
    margin-bottom: 8px;
}

.qv-delivery-option {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 12px;
    margin-bottom: 8px;
    border: 1px solid var(--slate-200);
    border-radius: 8px;
    cursor: pointer;
}
.qv-delivery-option:hover { border-color: var(--gray-400); }

.qv-delivery-option:has(input:checked) {
    border-color: var(--green-600);
    background: var(--brand-50);
}
.qv-delivery-option input { margin-top: 3px; }
.qv-delivery-option small { color: var(--slate-500); }

/* 2026-09-05 review: the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

changes.after:
/* Quote View: saved quote, order details and native Letter print layout.
 * Shared tokens and controls live in components.css/customer-documents.css.
 * This owner does not change the shared builder print stylesheet. */
@layer components.pages {
    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container {
        padding: var(--space-6);
        border: 1px solid var(--ui-line);
        border-radius: var(--radius-md);
        background: var(--ui-surface);
        box-shadow: var(--shadow-sm);
        font-size: var(--font-size-md);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .quote-header,
            .sw-sync-strip,
            .sw-sync-left,
            .sw-sync-right,
            .sw-manual-wo-left,
            .sw-actions-row,
            .quote-actions,
            .modal-header,
            .modal-footer,
            .qv-change-heading,
            .sw-vendor-head,
            .qv-deposit-strip-head,
            .qv-deposit-strip-form
        ) {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: var(--space-3);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-header {
        justify-content: space-between;
        padding-bottom: var(--space-5);
        border-bottom: 3px solid var(--brand-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .company-logo {
        display: block;
        width: 175px;
        height: auto;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .header-right {
        margin-left: auto;
        text-align: right;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .header-right
        h2 {
        margin: 0 0 var(--space-2);
        color: var(--brand-800);
        font-size: var(--font-size-xl);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container
        h2 {
        font-size: var(--font-size-lg);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container
        h3 {
        font-size: var(--font-size-md);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .status-badge,
            .sw-sync-pill,
            .sw-vendor-pill,
            .sw-shipping-mode-pill,
            .qv-deposit-strip-state,
            .sw-status-cell-value,
            .qv-timeline-staff-chip
        ) {
        display: inline-flex;
        align-items: center;
        gap: var(--space-1);
        border-radius: var(--radius-pill);
        padding: var(--space-1) var(--space-2);
        background: var(--gray-100);
        color: var(--ui-muted);
        font-size: var(--font-size-sm);
        font-weight: 600;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .status-accepted,
            .status-paid,
            .sw-sync-pill--imported,
            .sw-vendor-pill--complete,
            .sw-vendor-pill--shipped,
            .sw-status-cell-value--yes,
            .sw-shipping-mode-pill--active,
            .is-paid,
            .is-live
        ) {
        background: var(--brand-50);
        color: var(--brand-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .status-expired,
            .sw-vendor-pill--partial,
            .sw-status-cell-value--partial
        ) {
        background: var(--amber-100);
        color: var(--amber-900);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(.sw-vendor-pill--canceled, .sw-status-cell-value--no) {
        background: var(--red-50);
        color: var(--red-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(.loading-state, .error-state) {
        padding: var(--space-6);
        background: var(--ui-surface);
        border: 1px solid var(--ui-line);
        border-radius: var(--radius-md);
        text-align: center;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .loading-spinner {
        width: 40px;
        height: 40px;
        margin: 0 auto var(--space-4);
        border: 3px solid var(--ui-line);
        border-top-color: var(--brand-800);
        border-radius: var(--radius-pill);
        animation: qv-loading 1s linear infinite;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(.error-icon, .success-icon) {
        font-size: var(--font-size-display);
        font-weight: 700;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .error-icon {
        color: var(--red-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .success-icon {
        color: var(--brand-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-meta {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: var(--space-5);
        margin: var(--space-5) 0;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .meta-card {
        min-width: 0;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .meta-card
        h3 {
        margin: 0 0 var(--space-3);
        color: var(--ui-muted);
        text-transform: uppercase;
        letter-spacing: 0.06em;
        font-size: var(--font-size-xs);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .meta-card
        p {
        margin: var(--space-1) 0;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(.customer-name, .sw-shipping-recipient) {
        font-weight: 700;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .company-name,
            .customer-email,
            .customer-phone,
            .qv-muted,
            .qv-ship-method,
            .sw-financial-sublabel,
            .sw-sync-timestamp,
            .sw-sync-extorder,
            .qv-deposit-strip-help,
            .sw-manual-wo-help,
            .qv-warning-detail,
            .qv-change-time,
            .qv-timeline-detail,
            .qv-timeline-time,
            .qv-timeline-summary-meta,
            .sw-original-summary-meta,
            .deposit-note,
            .sw-vendor-note,
            .sw-vendor-eta,
            .sw-vendor-empty,
            .sw-notes-footer,
            .footer-bottom
        ) {
        color: var(--ui-muted);
        font-size: var(--font-size-sm);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .date-row,
            .total-row,
            .deposit-line,
            .sw-financial-row,
            .sw-shipping-meta-row
        ) {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        gap: var(--space-3);
        padding: var(--space-1) 0;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(.date-row .label, .sw-shipping-meta-label, .sw-financial-label) {
