/* Quote View: saved quote, order details and native Letter print layout.
 * Shared tokens and controls live in components.css/customer-documents.css.
 * This owner does not change the shared builder print stylesheet. */
@layer components.pages {
    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container {
        padding: var(--space-6);
        border: 1px solid var(--ui-line);
        border-radius: var(--radius-md);
        background: var(--ui-surface);
        box-shadow: var(--shadow-sm);
        font-size: var(--font-size-md);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
            .quote-header,
            .sw-sync-strip,
            .sw-sync-left,
            .sw-sync-right,
            .sw-manual-wo-left,
            .sw-actions-row,
            .quote-actions,
            .modal-header,
            .modal-footer,
            .qv-change-heading,
            .sw-vendor-head,
            .qv-deposit-strip-head,
            .qv-deposit-strip-form
        ) {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: var(--space-3);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-header {
        justify-content: space-between;
        padding-bottom: var(--space-5);
        border-bottom: 3px solid var(--brand-800);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .company-logo {
        display: block;
        width: 175px;
        height: auto;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .header-right {
        margin-left: auto;
        text-align: right;
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .header-right
        h2 {
        margin: 0 0 var(--space-2);
        color: var(--brand-800);
        font-size: var(--font-size-xl);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container
        h2 {
        font-size: var(--font-size-lg);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        .quote-container
        h3 {
        font-size: var(--font-size-md);
    }

    :where([data-ui="unified"][data-customer-document="quote-view"])
        :is(
