                .sw-designs-artwork-card
            ) {
            break-inside: avoid;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            :is(h2, h3) {
            break-after: avoid;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            :is(
                .quote-items,
                .sw-notes-section,
                .sw-designs-section,
                .sw-status-section,
                .sw-vendor-section,
                .sw-financial-section,
                .sw-shipping-section,
                .cust-art-section,
                .quote-footer
            ) {
            margin: 14px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .quote-footer {
            padding-top: 8px;
            break-inside: avoid;
            margin: 10px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .footer-content {
            grid-template-columns: 1fr 1fr;
            gap: 16px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .footer-section
            h2 {
            font-size: 12px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .footer-bottom {
            margin-top: 6px;
            font-size: 10px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .quote-totals {
            margin: 10px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .grand-total {
            font-size: 16px;
            padding-top: 6px;
            margin-top: 4px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .totals-card {
            padding: 12px;
            width: 320px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .deposit-card {
            padding: 12px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .print-only-terms {
            display: block;
            font-size: 11px;
            break-inside: avoid;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            :is(.cust-art-grid, .sw-designs-artwork-grid) {
            grid-template-columns: repeat(3, minmax(0, 1fr));
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            :is(.cust-art-thumb, .sw-designs-artwork-thumb) {
            height: 100px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-status-grid {
            grid-template-columns: repeat(5, minmax(0, 1fr));
            gap: 8px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-shipping-meta {
            grid-template-columns: repeat(3, minmax(0, 1fr));
            margin-bottom: 8px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .date-row {
            padding: 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .embroidery-info {
            padding: 8px;
            margin-bottom: 10px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .special-notes-card {
            padding: 10px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .special-notes-card
            h3 {
            margin: 0 0 6px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .total-row {
            padding: 2px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .total-quantity {
            margin-top: 6px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .billing-block {
            margin-top: 6px;
            padding-top: 6px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .billing-block
            p {
            margin: 2px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-status-cell {
            padding: 8px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-status-cell-label {
            margin-bottom: 4px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-notes-list
            li {
            margin: 4px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-financial-row {
            padding: 2px 0;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-financial-sublabel {
            display: inline;
            margin-left: 4px;
        }

        :where([data-ui="unified"][data-customer-document="quote-view"])
            .sw-shipping-address-block {
            padding: 8px;
        }
    }
}

